constexpr const BonusDefinition* FindBonusDefinition(std::uint32_t id) noexcept
{
    for (const auto& definition : BonusDefinitions)
        if (definition.id == id) return &definition;
    return nullptr;
}
constexpr const BonusDefinition* FindBonusDefinition(BonusId id) noexcept
{
    return FindBonusDefinition(static_cast<std::uint32_t>(id));
}
